        AND job_name LIKE CONCAT('%', #{jobName}, '%')


        AND city LIKE CONCAT('%', #{city}, '%')


        AND CAST(REPLACE(REPLACE(salary, 'k', ''), 'K', '') AS UNSIGNED) >= #{salaryMin}


        AND CAST(REPLACE(REPLACE(salary, 'k', ''), 'K', '') AS UNSIGNED) <= #{salaryMax}


